refentry.refsect1:
&reftitle.description;
public boolYaf_Route_Map::route Yaf_Request_Abstractrequest
Route the request by mapping the whole URI to a controller name or an action name: the path segments of the URI are joined with underscores to form the name. When the route was constructed with the controller prefer flag on, the result is set as the controller name, otherwise as the action name.

  &reftitle.parameters;


    request

The Yaf_Request_Abstract instance to route.

  &reftitle.examples;

   Yaf_Route_Map::route example


<?php
$request = new Yaf_Request_Simple("CLI");
$request->setRequestUri("/product/foo/bar");

$route = new Yaf_Route_Map();
var_dump($route->route($request));
var_dump($request->getActionName());
?>


   &example.outputs.similar;


bool(true)
string(15) "product_foo_bar"




   Yaf_Route_Map::route example


<?php
$request = new Yaf_Request_Simple("CLI");
$request->setRequestUri("/user/list/_/foo/22");

$route = new Yaf_Route_Map(true, "_");
var_dump($route->route($request));
var_dump($request->getControllerName());
var_dump($request->getParam("foo"));
?>


   &example.outputs.similar;


bool(true)
string(9) "User_List"
string(2) "22"
